// Typed Reactive Form with nonNullable
interface RegisterForm {
  email: FormControl<string>;
  password: FormControl<string>;
  confirmPassword: FormControl<string>;
}

this.form = new FormGroup<RegisterForm>({
  email: new FormControl('', {
    nonNullable: true,
    validators: [Validators.required, Validators.email],
    asyncValidators: [this.emailExistsValidator()],
    updateOn: 'blur'
  }),
  password: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.minLength(8)] }),
  confirmPassword: new FormControl('', { nonNullable: true, validators: [Validators.required] })
}, { validators: [passwordMatchValidator] });

// Cross-field validator
function passwordMatchValidator(group: AbstractControl): ValidationErrors | null {
  const pw = group.get('password')?.value;
  const confirm = group.get('confirmPassword')?.value;
  return pw === confirm ? null : { passwordMismatch: true };
}

// Async validator: check email uniqueness
emailExistsValidator(): AsyncValidatorFn {
  return (ctrl: AbstractControl) =>
    of(ctrl.value).pipe(
      debounceTime(400),
      distinctUntilChanged(),
      switchMap(email => this.authService.checkEmailExists(email)),
      map(exists => exists ? { emailTaken: true } : null),
      catchError(() => of(null))  // don't break form on API error
    );
}

// ControlValueAccessor: custom star-rating form control
@Component({
  selector: 'star-rating',
  template: \`<button *ngFor="let s of stars" (click)="setValue(s)">{{ s <= value ? '★' : '☆' }}</button>\`,
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: StarRatingComponent, multi: true }]
})
export class StarRatingComponent implements ControlValueAccessor {
  stars = [1, 2, 3, 4, 5];
  value = 0;
  onChange = (_: number) => {};
  onTouched = () => {};

  writeValue(val: number) { this.value = val ?? 0; }
  registerOnChange(fn: (v: number) => void) { this.onChange = fn; }
  registerOnTouched(fn: () => void) { this.onTouched = fn; }
  setValue(star: number) { this.value = star; this.onChange(star); this.onTouched(); }
}
